from pathlib import Path

p = Path('app/src/main/java/es/david/rumbo/ui/App.kt')
t = p.read_text()

def once(old: str, new: str, label: str):
    global t
    n = t.count(old)
    if n != 1:
        raise SystemExit(f'{label}: esperaba 1 aparición, hay {n}')
    t = t.replace(old, new, 1)

once(
'''import es.david.rumbo.logic.CertifiedDayWitnessEvaluator\n''',
'''import es.david.rumbo.logic.CertifiedDayWitnessEvaluator\nimport es.david.rumbo.logic.CulinarySatisfactionEvaluator\nimport es.david.rumbo.logic.CulinarySatisfactionIssueKind\nimport es.david.rumbo.logic.CulinarilySatisfactoryDayDiagnostic\nimport es.david.rumbo.logic.CulinarilySatisfactoryDaySearch\n''',
'imports'
)

